const menu = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#navigation');
function closeMenu(){navigation.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Открыть меню');}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');navigation.classList.toggle('open',open);});
navigation.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
const prices={individual:{90:{school:[4000,19000,36000],head:[5000,23750,45000]},120:{school:[5000,23750,45000],head:[6500,30875,58500]}},pair:{90:{school:[5000,23750,45000],head:[6500,30875,58500]},120:{school:[6500,30875,58500],head:[7500,35625,63000]}}};
let mode='individual',duration=90;
const currency=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
function updatePrices(){for(const role of ['school','head']){const p=prices[mode][duration][role];document.getElementById(role+'-price').textContent=currency(p[0]);document.getElementById(role+'-five').textContent=currency(p[1]);document.getElementById(role+'-ten').textContent=currency(p[2]);}document.querySelectorAll('.price-duration').forEach(e=>e.textContent='за '+duration+' минут'+(mode==='pair'?' / двоих':''));}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));updatePrices();}));
document.querySelectorAll('[data-duration]').forEach(b=>b.addEventListener('click',()=>{duration=Number(b.dataset.duration);document.querySelectorAll('[data-duration]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));updatePrices();}));
document.querySelectorAll('[data-direction]').forEach(a=>a.addEventListener('click',()=>{document.getElementById('direction').value=a.dataset.direction;}));
document.querySelectorAll('[data-trainer],[data-interest]').forEach(a=>a.addEventListener('click',()=>{document.getElementById('interest').value=a.dataset.trainer||a.dataset.interest;}));
document.getElementById('booking-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=String(data.get('name')).trim();if(!name){e.currentTarget.elements.name.setCustomValidity('Пожалуйста, укажите имя');e.currentTarget.elements.name.reportValidity();return;}const message='Здравствуйте! Меня зовут '+name+'.\nИнтересует: '+data.get('interest')+'.\nНаправление: '+data.get('direction')+'.\nУровень: '+data.get('level')+'.\nФормат: '+(mode==='pair'?'парное':'индивидуальное')+' занятие, '+duration+' минут.\n'+String(data.get('message')).trim();window.location.href='https://wa.me/79778576861?text='+encodeURIComponent(message);});
document.querySelector('input[name=name]').addEventListener('input',e=>e.target.setCustomValidity(''));
const reviews=[['Наталья','Илья очень внимательно относится к ученику, учитывает все нюансы. К концу занятия результативность выросла. Договорились продолжать заниматься дальше. Спасибо.'],['Сергей Ляховецкий','Пробное занятие с Ильёй прошло замечательно. Ясное и терпеливое преподнесение азов игры, полезные и при том интересные упражнения. Мы уже и сами стали чаще попадать в лузы, чем промахиваться!'],['Наталья','Спокойно и подробно объясняет, видит мои личные ошибки и помогает с ними разобраться, делает упор на постановку правильной техники. Спасибо за занятие! Буду продолжать.'],['Сергей','Очень доволен занятием. Индивидуальный и внимательный подход, полная вовлечённость в процесс обучения. Спасибо!'],['Елизавета','Я никогда раньше не занималась бильярдом. Илья посоветовал хороший клуб, выбрали удобное время. Тренировка прошла на одном дыхании: всё подробно объясняет понятными словами и сам показывает. С первого занятия я уже смогла правильно встать в стойку. Буду продолжать тренироваться.'],['Татьяна','Прекрасная школа бильярда! Илья Сурмин дал много необходимой информации, чтобы подобрать правильный кий. Наш тренер Ильяс Хайруллин сразу нашёл подход к ученику, хорошо всё объясняет, контролирует и поддерживает. Занимается дочь и ей очень нравится.']];
for(const [name,text] of reviews){const fig=document.createElement('figure');const quote=document.createElement('blockquote');quote.textContent=text;const caption=document.createElement('figcaption');caption.textContent=name;fig.append(quote,caption);document.getElementById('extra-reviews').append(fig);}
const awards=['068ab4b468e8fd65.jpg','e19819c9f8026552.jpg','c95c3b71ea84a2d2.jpg','5b426f1283123a67.jpg','ec50b46adf5d43eb.jpg','dbb0ba9c933be465.png','4399e833330945dd.jpg','54cabecca29997dd.jpg','5fbe980c1f312eb5.jpg'];
const dialog=document.getElementById('image-dialog');
awards.forEach((file,i)=>{const button=document.createElement('button');button.className='award-button';button.setAttribute('aria-label','Открыть диплом '+(i+1));const img=document.createElement('img');img.src='assets/'+file;img.alt='Диплом или награда Ильи Сурмина '+(i+1);img.loading='lazy';img.width=200;img.height=250;button.append(img);button.addEventListener('click',()=>{dialog.querySelector('img').src=img.src;dialog.querySelector('img').alt=img.alt;dialog.showModal();});document.getElementById('awards-gallery').append(button);});
dialog.querySelector('button').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
